insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('63beafbf-2ca1-5de6-8705-f714825317ca'::uuid, '91af23dc-ecce-5c52-800e-ad01af61572b'::uuid, 'single', '应用情境：判断某项技能是否达到临床或教学设定标准。此时最需要优先依据哪一概念？', '[{"key":"A","text":"心理测量"},{"key":"B","text":"效标参照"},{"key":"C","text":"心理测评"},{"key":"D","text":"心理测验"}]'::jsonb, '{"correct":"B"}'::jsonb, '该情境考查“效标参照”：根据预先规定的标准或掌握水平判断个体是否达到要求，而非主要比较群体位置。')
