insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('24f8bb7a-24e7-546f-816e-ca5f920b13ce'::uuid, '91af23dc-ecce-5c52-800e-ad01af61572b'::uuid, 'multi', '关于本章核心概念，下列哪些表述正确？（多选）', '[{"key":"A","text":"心理测量：依据心理学理论和规则，对心理特质或行为进行定量描述的活动。"},{"key":"B","text":"心理测评：围绕评估问题整合访谈、观察、记录、量表和标准化测验等信息，形成判断和建议的过程。"},{"key":"C","text":"心理测验：测验能直接测到完整的内在特质且没有误差。"},{"key":"D","text":"标准化：为让来访者表现更好而随意改变题目或提示。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A、B分别准确描述了“心理测量”和“心理测评”。C、D是常见误区，不能作为规范理解或操作依据。')
