insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('bbaf1e1f-0f7d-5a74-bcba-3663f4b33391'::uuid, '91af23dc-ecce-5c52-800e-ad01af61572b'::uuid, 'multi', '关于本章核心概念，下列哪些表述正确？（多选）', '[{"key":"A","text":"心理测验：按照标准程序测量行为样本，并借助计分和解释规则推断相关心理特征的工具或方法。"},{"key":"B","text":"标准化：在施测材料、指导语、环境、计分和解释等方面保持统一，以提高结果可比性。"},{"key":"C","text":"常模参照：百分位代表答对百分比，或任何常模都适合所有人。"},{"key":"D","text":"效标参照：效标参照必须依赖常模排名才能解释。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A、B分别准确描述了“心理测验”和“标准化”。C、D是常见误区，不能作为规范理解或操作依据。')
