insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('80515f78-09ec-5896-b7d8-c82350c04311'::uuid, '91af23dc-ecce-5c52-800e-ad01af61572b'::uuid, 'multi', '关于本章核心概念，下列哪些表述正确？（多选）', '[{"key":"A","text":"常模参照：把个体分数与具有明确特征的参照群体分布进行比较。"},{"key":"B","text":"效标参照：根据预先规定的标准或掌握水平判断个体是否达到要求，而非主要比较群体位置。"},{"key":"C","text":"评估问题：先选熟悉的量表，再寻找可以回答的问题。"},{"key":"D","text":"评估伦理：未经说明把结果提供给第三方，或超出胜任力解释。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A、B分别准确描述了“常模参照”和“效标参照”。C、D是常见误区，不能作为规范理解或操作依据。')
