insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('3529943a-f881-581c-ae22-9934cfb8a4e8'::uuid, '91af23dc-ecce-5c52-800e-ad01af61572b'::uuid, 'blank', '请填写概念：____是指依据心理学理论和规则，对心理特质或行为进行定量描述的活动。', NULL, '{"correct":["心理测量"]}'::jsonb, '答案是“心理测量”。')
