insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('86af6136-d4b5-5efb-85c4-afe6d1ffb4f5'::uuid, 'bf1d19d4-9fae-5256-9ef9-198755f5813a'::uuid, 'multi', '关于本章核心概念，下列哪些表述正确？（多选）', '[{"key":"A","text":"客位取向：检验外来构念和工具在新文化中的概念、测量与功能等效性并进行修订。"},{"key":"B","text":"条目库：围绕构念各维度建立数量充足、表述清晰且覆盖广泛的候选题目集合。"},{"key":"C","text":"内容效度：只由编制者本人觉得合理就足够。"},{"key":"D","text":"项目分析：只保留最容易题目就能提高量表质量。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A、B分别准确描述了“客位取向”和“条目库”。C、D是常见误区，不能作为规范理解或操作依据。')
