insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('46293d8c-6ca6-5cff-a3b3-e8464aff1996'::uuid, 'bf1d19d4-9fae-5256-9ef9-198755f5813a'::uuid, 'multi', '关于本章核心概念，下列哪些表述正确？（多选）', '[{"key":"A","text":"内容效度：专家和目标群体判断条目是否充分、适当地覆盖目标构念内容范围。"},{"key":"B","text":"项目分析：依据难度、区分度、条目—总分关系和选项表现等证据评价并筛选条目。"},{"key":"C","text":"因素分析：因素分析可以自动证明构念的全部效度。"},{"key":"D","text":"工具选择：选择最流行、最熟悉或最短的量表即可。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A、B分别准确描述了“内容效度”和“项目分析”。C、D是常见误区，不能作为规范理解或操作依据。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('5a3cc8c0-655d-5e24-a0cc-59a690751c9e'::uuid, 'bf1d19d4-9fae-5256-9ef9-198755f5813a'::uuid, 'blank', '请填写概念：____是指用理论和操作语言明确要测量的心理概念、维度、边界及与相近概念的区别。', NULL, '{"correct":["构念界定"]}'::jsonb, '答案是“构念界定”。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('3ae452b5-16de-5a66-bb6d-b2d691615848'::uuid, 'bf1d19d4-9fae-5256-9ef9-198755f5813a'::uuid, 'short', '简答题：说明“构念界定”与“主位取向”各自的含义，并指出在量表编制与工具选择中的应用要点。', NULL, '{"reference":"参考要点：\n1）构念界定：用理论和操作语言明确要测量的心理概念、维度、边界及与相近概念的区别。\n2）主位取向：从本土文化和目标群体经验出发发展特有构念与条目的量表开发方式。\n3）应用：开发孤独量表前区分孤独、社交隔离和社交焦虑。\n4）应用：研究“面子”时通过本土访谈形成条目。\n5）作答时应避免把两者混为一谈，并结合阶段目标说明使用时机。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('70bee29a-ff57-5bd5-92e2-f0913b1fe600'::uuid, 'bf1d19d4-9fae-5256-9ef9-198755f5813a'::uuid, 'case', '案例题：机构准备把国外成人焦虑量表直接翻译后用于中国青少年筛查。请列出开发与选择过程中必须补充的步骤。', NULL, '{"reference":"参考要点：重新界定目标构念和青少年适用性；采用规范翻译回译并检验概念与测量等效；结合本土访谈补充条目；专家审查和认知访谈；目标样本试测、项目分析、结构和信效度验证；建立合适常模与界值；明确筛查用途、知情同意和后续转介。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('88289234-dea5-53d9-bd78-c7af11183bb2'::uuid, '0a6bc1ae-9abf-5d72-9903-5c502f5e52d1'::uuid, 'single', '下列哪一概念最符合这一描述：“评估的时间、空间、隐私、座位、设备和沟通规则等条件。”？', '[{"key":"A","text":"评估设置"},{"key":"B","text":"知情同意"},{"key":"C","text":"记录"},{"key":"D","text":"录音录像同意"}]'::jsonb, '{"correct":"A"}'::jsonb, '正确概念是“评估设置”。选择安静隐秘空间并提前检查材料和设备。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('288d5689-b44f-5251-8ee6-b93c506b97a6'::uuid, '0a6bc1ae-9abf-5d72-9903-5c502f5e52d1'::uuid, 'single', '下列哪一概念最符合这一描述：“清楚说明姓名、角色、受训与督导情况、评估目的和可答疑内容。”？', '[{"key":"A","text":"记录"},{"key":"B","text":"专业自我介绍"},{"key":"C","text":"录音录像同意"},{"key":"D","text":"关系建立"}]'::jsonb, '{"correct":"B"}'::jsonb, '正确概念是“专业自我介绍”。受训咨询师向来访者说明自己在督导下工作。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('70d56e72-9765-5d27-8bd3-3cae36380125'::uuid, '0a6bc1ae-9abf-5d72-9903-5c502f5e52d1'::uuid, 'single', '下列哪一概念最符合这一描述：“在评估前说明目的、程序、风险收益、保密及例外、结果使用和自愿权利，并获得理解后的同意。”？', '[{"key":"A","text":"录音录像同意"},{"key":"B","text":"关系建立"},{"key":"C","text":"知情同意"},{"key":"D","text":"行为观察"}]'::jsonb, '{"correct":"C"}'::jsonb, '正确概念是“知情同意”。在录音、向第三方报告或敏感评估前单独确认。')
