insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('dbcee373-cce0-5c88-aa2a-835dfd7471bb'::uuid, '0a6bc1ae-9abf-5d72-9903-5c502f5e52d1'::uuid, 'single', '下列哪一概念最符合这一描述：“为了保持信息准确而进行的书面或电子记录，应说明原因、方式、保存和访问规则。”？', '[{"key":"A","text":"关系建立"},{"key":"B","text":"行为观察"},{"key":"C","text":"标准化偏离"},{"key":"D","text":"记录"}]'::jsonb, '{"correct":"D"}'::jsonb, '正确概念是“记录”。记录时不遮掩，并区分来访报告与咨询师推断。')
