insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('0eb8de92-76b2-5ea3-a1bb-75cb7791e69e'::uuid, '0a6bc1ae-9abf-5d72-9903-5c502f5e52d1'::uuid, 'short', '简答题：说明“评估设置”与“专业自我介绍”各自的含义，并指出在评估设置与临床技巧中的应用要点。', NULL, '{"reference":"参考要点：\n1）评估设置：评估的时间、空间、隐私、座位、设备和沟通规则等条件。\n2）专业自我介绍：清楚说明姓名、角色、受训与督导情况、评估目的和可答疑内容。\n3）应用：选择安静隐秘空间并提前检查材料和设备。\n4）应用：受训咨询师向来访者说明自己在督导下工作。\n5）作答时应避免把两者混为一谈，并结合阶段目标说明使用时机。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('801ca8b3-32d6-58b6-b655-dd1743447238'::uuid, '0a6bc1ae-9abf-5d72-9903-5c502f5e52d1'::uuid, 'case', '案例题：实习咨询师在来访者到场后才寻找量表，未介绍督导身份，打开录音后再让来访签同意书。请指出问题并重排规范流程。', NULL, '{"reference":"参考要点：应提前准备环境、量表和设备；先完成专业自我介绍、评估目的和督导说明；解释记录与录音用途、保密和撤回；获得理解后的同意再启动设备；建立关系并答疑；按标准流程实施，记录任何偏离和行为观察。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('1f2188cc-fda3-5704-b621-a8caee2cded3'::uuid, '0dc5685e-7f84-53e3-839d-fab15368fdb1'::uuid, 'single', '下列哪一概念最符合这一描述：“咨询开始阶段系统收集和整合信息，以理解问题、评估风险、确定目标与服务适配性的过程。”？', '[{"key":"A","text":"初始评估"},{"key":"B","text":"呈现问题"},{"key":"C","text":"心理社会历史"},{"key":"D","text":"当前功能"}]'::jsonb, '{"correct":"A"}'::jsonb, '正确概念是“初始评估”。首次会谈以信息收集和关系建立为主，不急于深入干预。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
