insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('912aec56-7c29-5bdf-b8bd-708b7819e07a'::uuid, '0dc5685e-7f84-53e3-839d-fab15368fdb1'::uuid, 'short', '简答题：说明“初始评估”与“转介问题”各自的含义，并指出在初始评估流程与信息收集中的应用要点。', NULL, '{"reference":"参考要点：\n1）初始评估：咨询开始阶段系统收集和整合信息，以理解问题、评估风险、确定目标与服务适配性的过程。\n2）转介问题：提出评估需求的核心问题，以及谁希望评估回答什么决策。\n3）应用：首次会谈以信息收集和关系建立为主，不急于深入干预。\n4）应用：区分来访者、家属、学校或医生各自希望回答的问题。\n5）作答时应避免把两者混为一谈，并结合阶段目标说明使用时机。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('690676a8-5649-5a3b-a193-6a872535d3ee'::uuid, '0dc5685e-7f84-53e3-839d-fab15368fdb1'::uuid, 'case', '案例题：一位来访者说“我最近状态不好，想做咨询”，并要求立即学习放松技术。请设计一次结构完整但不过度僵化的初始评估。', NULL, '{"reference":"参考要点：说明初评目的和边界；澄清呈现问题、时间线、诱发维持因素和功能影响；了解相关心理社会与治疗历史；观察精神状态；主动完成风险筛查；识别资源和保护因素；协商目标与预期；必要时使用量表；总结信息、说明局限并决定后续咨询、进一步评估或转介。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('56c8c92a-a19c-5a8e-9845-23a12decf674'::uuid, '0dc5685e-7f84-53e3-839d-fab15368fdb1'::uuid, 'single', '围绕“初始评估”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"初评就是填表和诊断，或必须一次完成全部问题。"},{"key":"B","text":"首次会谈以信息收集和关系建立为主，不急于深入干预。"},{"key":"C","text":"依据概念进行判断：咨询开始阶段系统收集和整合信息，以理解问题、评估风险、确定目标与服务适配性的过程。"},{"key":"D","text":"向来访者说明：初评主要帮助我们了解情况、风险和目标，再决定合适的服务安排。"}]'::jsonb, '{"correct":"A"}'::jsonb, '应避免：初评就是填表和诊断，或必须一次完成全部问题。。规范依据是：咨询开始阶段系统收集和整合信息，以理解问题、评估风险、确定目标与服务适配性的过程。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('109790f9-1630-522a-bd83-1a0ce309fb82'::uuid, '0dc5685e-7f84-53e3-839d-fab15368fdb1'::uuid, 'single', '围绕“转介问题”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"区分来访者、家属、学校或医生各自希望回答的问题。"},{"key":"B","text":"把转介来源的标签直接当成结论。"},{"key":"C","text":"依据概念进行判断：提出评估需求的核心问题，以及谁希望评估回答什么决策。"},{"key":"D","text":"向来访者说明：我们先确认这次评估最需要回答什么，以及不同相关方的期待。"}]'::jsonb, '{"correct":"B"}'::jsonb, '应避免：把转介来源的标签直接当成结论。。规范依据是：提出评估需求的核心问题，以及谁希望评估回答什么决策。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('030a8aee-c487-555a-a1f0-ee431d53102f'::uuid, '0dc5685e-7f84-53e3-839d-fab15368fdb1'::uuid, 'single', '围绕“呈现问题”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"询问何时开始、如何变化、什么加重或缓解。"},{"key":"B","text":"依据概念进行判断：来访者当前最关注的症状、困扰、发生情境、频率、强度和功能影响。"},{"key":"C","text":"只记录症状名称，不了解时间线和影响。"},{"key":"D","text":"向来访者说明：我会了解困扰从何时开始、在哪些情况出现、怎样影响生活。"}]'::jsonb, '{"correct":"C"}'::jsonb, '应避免：只记录症状名称，不了解时间线和影响。。规范依据是：来访者当前最关注的症状、困扰、发生情境、频率、强度和功能影响。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('03fa11c0-b190-55c5-8c7f-ef6e02a3df51'::uuid, '0dc5685e-7f84-53e3-839d-fab15368fdb1'::uuid, 'single', '围绕“心理社会历史”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"从非指导叙述开始，再对关键时期进行有重点追问。"},{"key":"B","text":"依据概念进行判断：与问题相关的发展、家庭、教育、工作、关系、健康、治疗和重大事件信息。"},{"key":"C","text":"向来访者说明：我们只收集与理解当前问题相关的经历，你可以询问为什么需要这些信息。"},{"key":"D","text":"按清单机械盘问所有隐私，忽略评估问题。"}]'::jsonb, '{"correct":"D"}'::jsonb, '应避免：按清单机械盘问所有隐私，忽略评估问题。。规范依据是：与问题相关的发展、家庭、教育、工作、关系、健康、治疗和重大事件信息。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('5a1af64a-5828-5ad6-a394-1a6f47056749'::uuid, '0dc5685e-7f84-53e3-839d-fab15368fdb1'::uuid, 'single', '围绕“当前功能”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"症状分数不高就认为功能没有受损。"},{"key":"B","text":"请来访描述典型一天并比较问题发生前后变化。"},{"key":"C","text":"依据概念进行判断：个体在生活自理、学习工作、人际、睡眠、饮食和日常活动等方面的实际表现。"},{"key":"D","text":"向来访者说明：除了感受，我们也会了解它怎样影响你每天的生活。"}]'::jsonb, '{"correct":"A"}'::jsonb, '应避免：症状分数不高就认为功能没有受损。。规范依据是：个体在生活自理、学习工作、人际、睡眠、饮食和日常活动等方面的实际表现。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('565318a0-c2d5-566d-8681-2d488a2a1d5d'::uuid, '0dc5685e-7f84-53e3-839d-fab15368fdb1'::uuid, 'single', '围绕“精神状态检查”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"把会谈中的观察与来访自述分开记录。"},{"key":"B","text":"仅凭精神状态检查就推断完整人格或长期诊断。"},{"key":"C","text":"依据概念进行判断：对外观行为、意识定向、言语、情绪、思维、知觉、认知、洞察和判断等当前状态的结构化观察。"},{"key":"D","text":"向来访者说明：这部分记录你此刻的状态，帮助判断是否需要进一步评估。"}]'::jsonb, '{"correct":"B"}'::jsonb, '应避免：仅凭精神状态检查就推断完整人格或长期诊断。。规范依据是：对外观行为、意识定向、言语、情绪、思维、知觉、认知、洞察和判断等当前状态的结构化观察。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('92b13439-a63b-5100-a350-f0c6a469b02f'::uuid, 'e410a413-d030-59a7-8dd6-f759360e9016'::uuid, 'single', '下列哪一概念最符合这一描述：“把量表作为访谈和观察的补充，用于筛查、量化、监测和提出进一步询问，而非取代临床判断。”？', '[{"key":"A","text":"量表融合"},{"key":"B","text":"施测前准备"},{"key":"C","text":"计分质控"},{"key":"D","text":"分数解释"}]'::jsonb, '{"correct":"A"}'::jsonb, '正确概念是“量表融合”。抑郁量表高分后继续询问具体条目、功能和风险。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('ed95f151-bfd8-5860-ac5f-87ae2f8c46f7'::uuid, 'e410a413-d030-59a7-8dd6-f759360e9016'::uuid, 'single', '下列哪一概念最符合这一描述：“确认量表的年龄、语言、用途、常模、信效度、施测方式和当前问题相匹配。”？', '[{"key":"A","text":"计分质控"},{"key":"B","text":"工具适配"},{"key":"C","text":"分数解释"},{"key":"D","text":"多源整合"}]'::jsonb, '{"correct":"B"}'::jsonb, '正确概念是“工具适配”。为青少年选择有对应年龄常模和使用证据的工具。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('07fe5d8b-aab4-562d-98c4-c1f6feba4650'::uuid, 'e410a413-d030-59a7-8dd6-f759360e9016'::uuid, 'single', '下列哪一概念最符合这一描述：“熟悉指导语、计分、重点条目、材料设备和异常情况处理。”？', '[{"key":"A","text":"分数解释"},{"key":"B","text":"多源整合"},{"key":"C","text":"施测前准备"},{"key":"D","text":"初评报告"}]'::jsonb, '{"correct":"C"}'::jsonb, '正确概念是“施测前准备”。提前检查二维码、纸笔、年龄版本和计分规则。')
