insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('9e52c5bd-fc38-5f43-8354-187b563fe5f3'::uuid, 'e410a413-d030-59a7-8dd6-f759360e9016'::uuid, 'single', '下列哪一概念最符合这一描述：“用清晰结构记录转介问题、方法、行为观察、结果、整合解释、局限和建议。”？', '[{"key":"A","text":"量表融合"},{"key":"B","text":"工具适配"},{"key":"C","text":"初评报告"},{"key":"D","text":"施测前准备"}]'::jsonb, '{"correct":"C"}'::jsonb, '正确概念是“初评报告”。区分事实、来访报告、测验结果和专业推断。')
