insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('6f603a3e-2214-5363-a0de-e7877d911ef9'::uuid, 'e410a413-d030-59a7-8dd6-f759360e9016'::uuid, 'single', '下列哪一概念最符合这一描述：“以可理解、合作和优势取向方式解释过程、结果、局限和建议，并收集来访反应。”？', '[{"key":"A","text":"工具适配"},{"key":"B","text":"施测前准备"},{"key":"C","text":"计分质控"},{"key":"D","text":"结果反馈"}]'::jsonb, '{"correct":"D"}'::jsonb, '正确概念是“结果反馈”。先回到转介问题，使用视觉材料，指出优势并讨论下一步。')
