insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('90469494-faba-5ef8-a4c3-b37738c7bd38'::uuid, 'e410a413-d030-59a7-8dd6-f759360e9016'::uuid, 'single', '应用情境：抑郁量表高分后继续询问具体条目、功能和风险。此时最需要优先依据哪一概念？', '[{"key":"A","text":"量表融合"},{"key":"B","text":"计分质控"},{"key":"C","text":"分数解释"},{"key":"D","text":"多源整合"}]'::jsonb, '{"correct":"A"}'::jsonb, '该情境考查“量表融合”：把量表作为访谈和观察的补充，用于筛查、量化、监测和提出进一步询问，而非取代临床判断。')
