insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('d7b6ceda-bf3e-5192-adc0-6678e8339ff7'::uuid, 'e410a413-d030-59a7-8dd6-f759360e9016'::uuid, 'single', '应用情境：说明T分数位置、可信区间和常模适用范围。此时最需要优先依据哪一概念？', '[{"key":"A","text":"分数解释"},{"key":"B","text":"结果反馈"},{"key":"C","text":"量表融合"},{"key":"D","text":"工具适配"}]'::jsonb, '{"correct":"A"}'::jsonb, '该情境考查“分数解释”：结合原始分、标准分、百分位、界值、误差和常模条件说明结果意义。')
