insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('eb449439-2432-5a92-8018-66921c5c64c5'::uuid, 'e410a413-d030-59a7-8dd6-f759360e9016'::uuid, 'single', '应用情境：家长报告、儿童自述和学校观察不一致时分析情境差异。此时最需要优先依据哪一概念？', '[{"key":"A","text":"量表融合"},{"key":"B","text":"多源整合"},{"key":"C","text":"工具适配"},{"key":"D","text":"施测前准备"}]'::jsonb, '{"correct":"B"}'::jsonb, '该情境考查“多源整合”：比较访谈、观察、量表、记录和多信息提供者的一致与不一致，形成综合判断。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('f17e59de-90bf-5905-89d2-11e7552b99ab'::uuid, 'e410a413-d030-59a7-8dd6-f759360e9016'::uuid, 'multi', '关于本章核心概念，下列哪些表述正确？（多选）', '[{"key":"A","text":"量表融合：把量表作为访谈和观察的补充，用于筛查、量化、监测和提出进一步询问，而非取代临床判断。"},{"key":"B","text":"工具适配：确认量表的年龄、语言、用途、常模、信效度、施测方式和当前问题相匹配。"},{"key":"C","text":"施测前准备：边看说明书边施测，或不知道关键风险条目。"},{"key":"D","text":"计分质控：总分正确就不必检查单个条目和作答质量。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A、B分别准确描述了“量表融合”和“工具适配”。C、D是常见误区，不能作为规范理解或操作依据。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('d127113d-ff31-503e-9dfe-a63834d93b45'::uuid, 'e410a413-d030-59a7-8dd6-f759360e9016'::uuid, 'multi', '关于本章核心概念，下列哪些表述正确？（多选）', '[{"key":"A","text":"施测前准备：熟悉指导语、计分、重点条目、材料设备和异常情况处理。"},{"key":"B","text":"计分质控：计分前检查漏答、无效反应和重点条目，再按规定转换和复核分数。"},{"key":"C","text":"分数解释：把百分位当正确率，或把界值当绝对诊断线。"},{"key":"D","text":"多源整合：选择最符合咨询师预期的一项信息，其余忽略。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A、B分别准确描述了“施测前准备”和“计分质控”。C、D是常见误区，不能作为规范理解或操作依据。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('40c35b20-7fd7-5bfe-ba9e-fba8374698bf'::uuid, 'e410a413-d030-59a7-8dd6-f759360e9016'::uuid, 'multi', '关于本章核心概念，下列哪些表述正确？（多选）', '[{"key":"A","text":"分数解释：结合原始分、标准分、百分位、界值、误差和常模条件说明结果意义。"},{"key":"B","text":"多源整合：比较访谈、观察、量表、记录和多信息提供者的一致与不一致，形成综合判断。"},{"key":"C","text":"初评报告：堆砌分数而不回答转介问题，或把推断写成事实。"},{"key":"D","text":"结果反馈：照读报告、使用大量术语或只讲缺陷。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A、B分别准确描述了“分数解释”和“多源整合”。C、D是常见误区，不能作为规范理解或操作依据。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('8612e7d2-3a20-523d-9671-a663d73b8c31'::uuid, 'e410a413-d030-59a7-8dd6-f759360e9016'::uuid, 'blank', '请填写概念：____是指把量表作为访谈和观察的补充，用于筛查、量化、监测和提出进一步询问，而非取代临床判断。', NULL, '{"correct":["量表融合"]}'::jsonb, '答案是“量表融合”。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('bf926aa1-35d2-5ada-ad0f-cf5056b1a288'::uuid, 'e410a413-d030-59a7-8dd6-f759360e9016'::uuid, 'short', '简答题：说明“量表融合”与“工具适配”各自的含义，并指出在初评量表、报告与结果反馈中的应用要点。', NULL, '{"reference":"参考要点：\n1）量表融合：把量表作为访谈和观察的补充，用于筛查、量化、监测和提出进一步询问，而非取代临床判断。\n2）工具适配：确认量表的年龄、语言、用途、常模、信效度、施测方式和当前问题相匹配。\n3）应用：抑郁量表高分后继续询问具体条目、功能和风险。\n4）应用：为青少年选择有对应年龄常模和使用证据的工具。\n5）作答时应避免把两者混为一谈，并结合阶段目标说明使用时机。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('7ca0b74a-51ff-5723-a083-9ca881c2cf9a'::uuid, 'e410a413-d030-59a7-8dd6-f759360e9016'::uuid, 'case', '案例题：初评中来访者抑郁量表总分中等，但自杀条目为3分；访谈时否认严重问题。请说明计分、询问、整合、报告和反馈步骤。', NULL, '{"reference":"参考要点：先检查作答完整性和计分；风险条目优先于总分，立即直接跟进想法、计划、意图、手段和保护因素；比较量表、访谈、行为观察及可能的最小化反应；必要时启动危机流程；报告区分数据与推断并说明局限；反馈使用清晰语言、回归安全和后续计划。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('9fbea905-f351-568e-8f0f-e19e81712aa6'::uuid, 'e410a413-d030-59a7-8dd6-f759360e9016'::uuid, 'single', '围绕“量表融合”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"只要总分超过界值就直接诊断。"},{"key":"B","text":"抑郁量表高分后继续询问具体条目、功能和风险。"},{"key":"C","text":"依据概念进行判断：把量表作为访谈和观察的补充，用于筛查、量化、监测和提出进一步询问，而非取代临床判断。"},{"key":"D","text":"向来访者说明：量表帮助我们发现需要进一步了解的方向，不会单独决定诊断。"}]'::jsonb, '{"correct":"A"}'::jsonb, '应避免：只要总分超过界值就直接诊断。。规范依据是：把量表作为访谈和观察的补充，用于筛查、量化、监测和提出进一步询问，而非取代临床判断。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('a83aa6dd-8ae4-5dfb-9fe1-b83da35ca1a9'::uuid, 'e410a413-d030-59a7-8dd6-f759360e9016'::uuid, 'single', '围绕“工具适配”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"为青少年选择有对应年龄常模和使用证据的工具。"},{"key":"B","text":"只因量表简短或免费就使用。"},{"key":"C","text":"依据概念进行判断：确认量表的年龄、语言、用途、常模、信效度、施测方式和当前问题相匹配。"},{"key":"D","text":"向来访者说明：我们会选择适合你的年龄和问题、且有研究依据的工具。"}]'::jsonb, '{"correct":"B"}'::jsonb, '应避免：只因量表简短或免费就使用。。规范依据是：确认量表的年龄、语言、用途、常模、信效度、施测方式和当前问题相匹配。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('dc1f3194-1356-53ad-835d-c5ef9aff8689'::uuid, 'e410a413-d030-59a7-8dd6-f759360e9016'::uuid, 'single', '围绕“施测前准备”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"提前检查二维码、纸笔、年龄版本和计分规则。"},{"key":"B","text":"依据概念进行判断：熟悉指导语、计分、重点条目、材料设备和异常情况处理。"},{"key":"C","text":"边看说明书边施测，或不知道关键风险条目。"},{"key":"D","text":"向来访者说明：规范准备能减少流程差异，也避免遗漏重要信息。"}]'::jsonb, '{"correct":"C"}'::jsonb, '应避免：边看说明书边施测，或不知道关键风险条目。。规范依据是：熟悉指导语、计分、重点条目、材料设备和异常情况处理。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('c4e66282-020b-5829-b300-c76c014bff4b'::uuid, 'e410a413-d030-59a7-8dd6-f759360e9016'::uuid, 'single', '围绕“计分质控”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"发现风险条目非零时先跟进安全问题，而不是只算总分。"},{"key":"B","text":"依据概念进行判断：计分前检查漏答、无效反应和重点条目，再按规定转换和复核分数。"},{"key":"C","text":"向来访者说明：有些题目即使不影响总分，也可能提示需要立即进一步询问。"},{"key":"D","text":"总分正确就不必检查单个条目和作答质量。"}]'::jsonb, '{"correct":"D"}'::jsonb, '应避免：总分正确就不必检查单个条目和作答质量。。规范依据是：计分前检查漏答、无效反应和重点条目，再按规定转换和复核分数。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('56de4e5b-1407-57e0-945f-7d8c5f8318d1'::uuid, 'e410a413-d030-59a7-8dd6-f759360e9016'::uuid, 'single', '围绕“分数解释”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"把百分位当正确率，或把界值当绝对诊断线。"},{"key":"B","text":"说明T分数位置、可信区间和常模适用范围。"},{"key":"C","text":"依据概念进行判断：结合原始分、标准分、百分位、界值、误差和常模条件说明结果意义。"},{"key":"D","text":"向来访者说明：分数表示相对位置和风险线索，不是对你的固定定义。"}]'::jsonb, '{"correct":"A"}'::jsonb, '应避免：把百分位当正确率，或把界值当绝对诊断线。。规范依据是：结合原始分、标准分、百分位、界值、误差和常模条件说明结果意义。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('b2e18a83-08bd-58c7-9756-5ad449d4abba'::uuid, 'e410a413-d030-59a7-8dd6-f759360e9016'::uuid, 'single', '围绕“多源整合”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"家长报告、儿童自述和学校观察不一致时分析情境差异。"},{"key":"B","text":"选择最符合咨询师预期的一项信息，其余忽略。"},{"key":"C","text":"依据概念进行判断：比较访谈、观察、量表、记录和多信息提供者的一致与不一致，形成综合判断。"},{"key":"D","text":"向来访者说明：不同来源不一致并不一定是谁错了，可能反映不同情境下的表现。"}]'::jsonb, '{"correct":"B"}'::jsonb, '应避免：选择最符合咨询师预期的一项信息，其余忽略。。规范依据是：比较访谈、观察、量表、记录和多信息提供者的一致与不一致，形成综合判断。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('d3d29de6-17d3-5b4b-9965-5be0f6b4b651'::uuid, '66a65dae-2194-5ccd-a53e-79b345b078a9'::uuid, 'single', '下列哪一概念最符合这一描述：“关于死亡、自杀或不想活的想法，可从被动愿望到主动想法，需进一步评估。”？', '[{"key":"A","text":"自杀意念"},{"key":"B","text":"自杀意图"},{"key":"C","text":"手段可及性"},{"key":"D","text":"既往自杀行为"}]'::jsonb, '{"correct":"A"}'::jsonb, '正确概念是“自杀意念”。来访说“睡着不醒就好了”时继续询问频率、可控性和是否出现主动想法。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('2d787b94-9af5-53be-b7b5-af93c04b114c'::uuid, '66a65dae-2194-5ccd-a53e-79b345b078a9'::uuid, 'single', '下列哪一概念最符合这一描述：“关于自杀方法、时间、地点或步骤的具体构想，具体性和可行性会影响风险。”？', '[{"key":"A","text":"手段可及性"},{"key":"B","text":"自杀计划"},{"key":"C","text":"既往自杀行为"},{"key":"D","text":"危险与保护因素"}]'::jsonb, '{"correct":"B"}'::jsonb, '正确概念是“自杀计划”。询问是否想过怎么做、何时何地以及准备程度。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('fc09074c-1ad8-5769-a6c5-bf3c15967c0a'::uuid, '66a65dae-2194-5ccd-a53e-79b345b078a9'::uuid, 'single', '下列哪一概念最符合这一描述：“个体实施自杀行为的主观愿望、决心或预期死亡程度。”？', '[{"key":"A","text":"既往自杀行为"},{"key":"B","text":"危险与保护因素"},{"key":"C","text":"自杀意图"},{"key":"D","text":"安全计划"}]'::jsonb, '{"correct":"C"}'::jsonb, '正确概念是“自杀意图”。区分“想让痛苦停止”和“确实准备结束生命”的程度。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('1c0793f1-cba0-5953-beac-2f254920eb4c'::uuid, '66a65dae-2194-5ccd-a53e-79b345b078a9'::uuid, 'single', '下列哪一概念最符合这一描述：“个体能否获得计划所需工具、地点或条件，以及是否已做准备。”？', '[{"key":"A","text":"危险与保护因素"},{"key":"B","text":"安全计划"},{"key":"C","text":"紧急升级处置"},{"key":"D","text":"手段可及性"}]'::jsonb, '{"correct":"D"}'::jsonb, '正确概念是“手段可及性”。询问药物、武器、高处或其他手段是否可获得，并推动安全限制。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('3cf47901-660b-5efb-a502-17e1e25bf705'::uuid, '66a65dae-2194-5ccd-a53e-79b345b078a9'::uuid, 'single', '下列哪一概念最符合这一描述：“既往尝试、预备行为、中止或被阻止的行为，是评估未来风险的重要信息。”？', '[{"key":"A","text":"既往自杀行为"},{"key":"B","text":"安全计划"},{"key":"C","text":"紧急升级处置"},{"key":"D","text":"自杀意念"}]'::jsonb, '{"correct":"A"}'::jsonb, '正确概念是“既往自杀行为”。询问次数、方法、医疗严重度、意图和当时后果。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('3d4996cc-b087-50cf-8976-b0e754d1adc4'::uuid, '66a65dae-2194-5ccd-a53e-79b345b078a9'::uuid, 'single', '下列哪一概念最符合这一描述：“危险因素增加风险，保护因素提供连接、责任、价值、支持和求助可能，两者需动态整合。”？', '[{"key":"A","text":"紧急升级处置"},{"key":"B","text":"危险与保护因素"},{"key":"C","text":"自杀意念"},{"key":"D","text":"自杀计划"}]'::jsonb, '{"correct":"B"}'::jsonb, '正确概念是“危险与保护因素”。同时评估物质使用、绝望、近期丧失以及家庭支持、求助意愿等。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('f838ece0-db7e-5598-aae9-86072fc9113d'::uuid, '66a65dae-2194-5ccd-a53e-79b345b078a9'::uuid, 'single', '下列哪一概念最符合这一描述：“与来访者共同制定的分步危机应对方案，包括预警信号、内部应对、社会支持、专业资源和限制手段。”？', '[{"key":"A","text":"自杀意念"},{"key":"B","text":"自杀计划"},{"key":"C","text":"安全计划"},{"key":"D","text":"自杀意图"}]'::jsonb, '{"correct":"C"}'::jsonb, '正确概念是“安全计划”。写下具体联系人、机构、急救渠道和可执行步骤。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('b2fe1edb-1075-5f8d-90a9-cb88bc6ea409'::uuid, '66a65dae-2194-5ccd-a53e-79b345b078a9'::uuid, 'single', '下列哪一概念最符合这一描述：“当存在迫近危险或无法维持安全时，依据法律伦理和机构流程启动家属支持、急诊、报警或其他紧急资源。”？', '[{"key":"A","text":"自杀计划"},{"key":"B","text":"自杀意图"},{"key":"C","text":"手段可及性"},{"key":"D","text":"紧急升级处置"}]'::jsonb, '{"correct":"D"}'::jsonb, '正确概念是“紧急升级处置”。明确计划、意图、手段且无法合作安全时不让来访独自离开。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('d35936eb-1b26-5add-b637-6101228b7841'::uuid, '66a65dae-2194-5ccd-a53e-79b345b078a9'::uuid, 'single', '应用情境：来访说“睡着不醒就好了”时继续询问频率、可控性和是否出现主动想法。此时最需要优先依据哪一概念？', '[{"key":"A","text":"自杀意念"},{"key":"B","text":"手段可及性"},{"key":"C","text":"既往自杀行为"},{"key":"D","text":"危险与保护因素"}]'::jsonb, '{"correct":"A"}'::jsonb, '该情境考查“自杀意念”：关于死亡、自杀或不想活的想法，可从被动愿望到主动想法，需进一步评估。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('13e8c034-2f4f-5260-a634-9e4a4a791eec'::uuid, '66a65dae-2194-5ccd-a53e-79b345b078a9'::uuid, 'single', '应用情境：询问是否想过怎么做、何时何地以及准备程度。此时最需要优先依据哪一概念？', '[{"key":"A","text":"既往自杀行为"},{"key":"B","text":"自杀计划"},{"key":"C","text":"危险与保护因素"},{"key":"D","text":"安全计划"}]'::jsonb, '{"correct":"B"}'::jsonb, '该情境考查“自杀计划”：关于自杀方法、时间、地点或步骤的具体构想，具体性和可行性会影响风险。')
