insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('95e7b894-3dc2-5095-a7a9-d7e861163730'::uuid, '66a65dae-2194-5ccd-a53e-79b345b078a9'::uuid, 'single', '应用情境：区分“想让痛苦停止”和“确实准备结束生命”的程度。此时最需要优先依据哪一概念？', '[{"key":"A","text":"危险与保护因素"},{"key":"B","text":"安全计划"},{"key":"C","text":"自杀意图"},{"key":"D","text":"紧急升级处置"}]'::jsonb, '{"correct":"C"}'::jsonb, '该情境考查“自杀意图”：个体实施自杀行为的主观愿望、决心或预期死亡程度。')
