insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('786e18c0-88c0-586f-bdab-3fcf437576ee'::uuid, '66a65dae-2194-5ccd-a53e-79b345b078a9'::uuid, 'single', '应用情境：询问药物、武器、高处或其他手段是否可获得，并推动安全限制。此时最需要优先依据哪一概念？', '[{"key":"A","text":"安全计划"},{"key":"B","text":"紧急升级处置"},{"key":"C","text":"自杀意念"},{"key":"D","text":"手段可及性"}]'::jsonb, '{"correct":"D"}'::jsonb, '该情境考查“手段可及性”：个体能否获得计划所需工具、地点或条件，以及是否已做准备。')
