insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('3cf0141f-2ee8-5e17-bf50-815540d951f5'::uuid, '66a65dae-2194-5ccd-a53e-79b345b078a9'::uuid, 'single', '应用情境：询问次数、方法、医疗严重度、意图和当时后果。此时最需要优先依据哪一概念？', '[{"key":"A","text":"既往自杀行为"},{"key":"B","text":"紧急升级处置"},{"key":"C","text":"自杀意念"},{"key":"D","text":"自杀计划"}]'::jsonb, '{"correct":"A"}'::jsonb, '该情境考查“既往自杀行为”：既往尝试、预备行为、中止或被阻止的行为，是评估未来风险的重要信息。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('e96b07b7-164c-5e82-be81-e330bf2bf615'::uuid, '66a65dae-2194-5ccd-a53e-79b345b078a9'::uuid, 'single', '应用情境：同时评估物质使用、绝望、近期丧失以及家庭支持、求助意愿等。此时最需要优先依据哪一概念？', '[{"key":"A","text":"自杀意念"},{"key":"B","text":"危险与保护因素"},{"key":"C","text":"自杀计划"},{"key":"D","text":"自杀意图"}]'::jsonb, '{"correct":"B"}'::jsonb, '该情境考查“危险与保护因素”：危险因素增加风险，保护因素提供连接、责任、价值、支持和求助可能，两者需动态整合。')
