insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('87fa87db-1373-5e35-9ef3-1931ecd0912c'::uuid, 'ce097296-ecb6-5531-b4c3-fb6ec42e4d6d'::uuid, 'single', '下列哪一概念最符合这一描述：“与目标特质无关但系统影响自陈结果的反应方式，如社会赞许、随机、极端或默认同意。”？', '[{"key":"A","text":"作答风格"},{"key":"B","text":"人格评估多方法"},{"key":"C","text":"人格反馈"},{"key":"D","text":"人格"}]'::jsonb, '{"correct":"A"}'::jsonb, '正确概念是“作答风格”。检查效度指标、作答时间和前后不一致。')
