insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('d57a6709-a4d0-5abd-84f2-4c5e2b1b422a'::uuid, 'ce097296-ecb6-5531-b4c3-fb6ec42e4d6d'::uuid, 'single', '下列哪一概念最符合这一描述：“将特质或临床量表分数与适配参照群体比较，并结合可信区间和基率解释。”？', '[{"key":"A","text":"人格反馈"},{"key":"B","text":"人格常模解释"},{"key":"C","text":"人格"},{"key":"D","text":"结构型人格测验"}]'::jsonb, '{"correct":"B"}'::jsonb, '正确概念是“人格常模解释”。说明高分是相对位置，不等于病理诊断。')
