insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('30470386-1412-52e5-b1dc-e9c76a98d919'::uuid, 'ce097296-ecb6-5531-b4c3-fb6ec42e4d6d'::uuid, 'blank', '请填写概念：____是指相对稳定且有组织的心理特征与机制，影响个体与内部、物理和社会环境的交互与适应。', NULL, '{"correct":["人格"]}'::jsonb, '答案是“人格”。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('0cfeddc4-1c34-529b-8b0e-002880df998a'::uuid, 'ce097296-ecb6-5531-b4c3-fb6ec42e4d6d'::uuid, 'short', '简答题：说明“人格”与“结构型人格测验”各自的含义，并指出在人格测评基础与五因素模型中的应用要点。', NULL, '{"reference":"参考要点：\n1）人格：相对稳定且有组织的心理特征与机制，影响个体与内部、物理和社会环境的交互与适应。\n2）结构型人格测验：使用明确题目、固定反应和标准计分，通常具有常模和信效度证据的自陈或他评工具。\n3）应用：解释人格时同时考虑稳定倾向和情境中的行为变化。\n4）应用：用标准化人格量表比较特质并检查效度指标。\n5）作答时应避免把两者混为一谈，并结合阶段目标说明使用时机。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('6b98aa58-9054-5ce6-806a-43dbc8a4a85e'::uuid, 'ce097296-ecb6-5531-b4c3-fb6ec42e4d6d'::uuid, 'case', '案例题：来访者完成网络五因素测验后认为自己“神经质高，所以性格有病且无法改变”。请说明咨询师应如何解释与进一步评估。', NULL, '{"reference":"参考要点：解释五因素是连续特质而非疾病类型；神经质高表示更易体验负性情绪，不等于人格障碍；核查工具、常模和作答质量；结合访谈、功能、情境和多源信息；反馈适应与风险两面；讨论可学习的调节方式，避免污名化和决定论。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('c350bded-fec1-5f70-bc34-d25ce072f2df'::uuid, 'ce097296-ecb6-5531-b4c3-fb6ec42e4d6d'::uuid, 'single', '围绕“人格”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"人格等同于固定不变的行为，或一次表现即可定义人格。"},{"key":"B","text":"解释人格时同时考虑稳定倾向和情境中的行为变化。"},{"key":"C","text":"依据概念进行判断：相对稳定且有组织的心理特征与机制，影响个体与内部、物理和社会环境的交互与适应。"},{"key":"D","text":"向来访者说明：人格描述相对稳定的倾向，但人在不同情境中仍可能表现不同。"}]'::jsonb, '{"correct":"A"}'::jsonb, '应避免：人格等同于固定不变的行为，或一次表现即可定义人格。。规范依据是：相对稳定且有组织的心理特征与机制，影响个体与内部、物理和社会环境的交互与适应。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('eb57a0bc-3625-56b0-83ee-e1d5bdcdc553'::uuid, 'ce097296-ecb6-5531-b4c3-fb6ec42e4d6d'::uuid, 'single', '围绕“结构型人格测验”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"用标准化人格量表比较特质并检查效度指标。"},{"key":"B","text":"所有自陈答案都绝对真实且不受作答风格影响。"},{"key":"C","text":"依据概念进行判断：使用明确题目、固定反应和标准计分，通常具有常模和信效度证据的自陈或他评工具。"},{"key":"D","text":"向来访者说明：这类量表流程和计分较统一，但仍需检查作答是否可信。"}]'::jsonb, '{"correct":"B"}'::jsonb, '应避免：所有自陈答案都绝对真实且不受作答风格影响。。规范依据是：使用明确题目、固定反应和标准计分，通常具有常模和信效度证据的自陈或他评工具。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('1c4b51bf-e1cf-58d7-ac5f-659bba99282e'::uuid, 'ce097296-ecb6-5531-b4c3-fb6ec42e4d6d'::uuid, 'single', '围绕“投射测验”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"使用规范评分体系并与其他资料结合。"},{"key":"B","text":"依据概念进行判断：使用相对模糊、非结构化刺激，引出个体的知觉、需要和主题，评分解释更依赖专业系统。"},{"key":"C","text":"看一张图就能直接读出潜意识，或投射结果可以单独诊断。"},{"key":"D","text":"向来访者说明：它提供一些可能主题，需要规范评分并结合其他信息，不能单独下结论。"}]'::jsonb, '{"correct":"C"}'::jsonb, '应避免：看一张图就能直接读出潜意识，或投射结果可以单独诊断。。规范依据是：使用相对模糊、非结构化刺激，引出个体的知觉、需要和主题，评分解释更依赖专业系统。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('8bfb9488-750f-5fa4-a7a3-9de1a2440f48'::uuid, 'ce097296-ecb6-5531-b4c3-fb6ec42e4d6d'::uuid, 'single', '围绕“五因素模型”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"用连续维度描述倾向，而不是贴好坏标签。"},{"key":"B","text":"依据概念进行判断：用开放性、尽责性、外向性、宜人性和神经质描述广泛人格特质维度。"},{"key":"C","text":"向来访者说明：五个维度描述倾向，不是把人分成五类；高低是否有利要看情境。"},{"key":"D","text":"五个维度就是五种人格类型，分数高低都有统一好坏。"}]'::jsonb, '{"correct":"D"}'::jsonb, '应避免：五个维度就是五种人格类型，分数高低都有统一好坏。。规范依据是：用开放性、尽责性、外向性、宜人性和神经质描述广泛人格特质维度。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('58e8140b-b58f-5d2f-ae91-2f7efa8482e6'::uuid, 'ce097296-ecb6-5531-b4c3-fb6ec42e4d6d'::uuid, 'single', '围绕“作答风格”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"量表有很多题就能自动消除作答偏差。"},{"key":"B","text":"检查效度指标、作答时间和前后不一致。"},{"key":"C","text":"依据概念进行判断：与目标特质无关但系统影响自陈结果的反应方式，如社会赞许、随机、极端或默认同意。"},{"key":"D","text":"向来访者说明：结果也会受答题方式影响，因此需要先确认作答是否有效。"}]'::jsonb, '{"correct":"A"}'::jsonb, '应避免：量表有很多题就能自动消除作答偏差。。规范依据是：与目标特质无关但系统影响自陈结果的反应方式，如社会赞许、随机、极端或默认同意。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('4d273f59-1281-5785-a736-ef4b81c2a282'::uuid, 'ce097296-ecb6-5531-b4c3-fb6ec42e4d6d'::uuid, 'single', '围绕“人格常模解释”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"说明高分是相对位置，不等于病理诊断。"},{"key":"B","text":"任何显著高分都表示人格障碍。"},{"key":"C","text":"依据概念进行判断：将特质或临床量表分数与适配参照群体比较，并结合可信区间和基率解释。"},{"key":"D","text":"向来访者说明：分数较高说明某种倾向更突出，但是否构成问题还要看功能和情境。"}]'::jsonb, '{"correct":"B"}'::jsonb, '应避免：任何显著高分都表示人格障碍。。规范依据是：将特质或临床量表分数与适配参照群体比较，并结合可信区间和基率解释。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('aacaebcf-7fa4-5600-9409-c6a8a83aab73'::uuid, '61bfb40e-f681-5397-b982-68e86ff747d4'::uuid, 'single', '下列哪一概念最符合这一描述：“通过比较已知效标群体与对照群体的作答差异筛选条目，而非只靠题目表面内容。”？', '[{"key":"A","text":"经验效标法"},{"key":"B","text":"临床量表"},{"key":"C","text":"剖面解释"},{"key":"D","text":"人格病理"}]'::jsonb, '{"correct":"A"}'::jsonb, '正确概念是“经验效标法”。理解MMPI量表名称不等于条目内容或单一诊断。')
