insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('1ef029b2-ba27-59c2-8cbb-0ecc87a07620'::uuid, '61bfb40e-f681-5397-b982-68e86ff747d4'::uuid, 'single', '应用情境：同时描述负性情感、疏离等特质及自我人际功能。此时最需要优先依据哪一概念？', '[{"key":"A","text":"经验效标法"},{"key":"B","text":"维度评估"},{"key":"C","text":"效度量表"},{"key":"D","text":"临床量表"}]'::jsonb, '{"correct":"B"}'::jsonb, '该情境考查“维度评估”：在连续维度上描述人格特质和功能严重度，保留个体差异和变化空间。')
