insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('9734e595-0f00-58f0-97f3-c622db641639'::uuid, '61bfb40e-f681-5397-b982-68e86ff747d4'::uuid, 'multi', '关于本章核心概念，下列哪些表述正确？（多选）', '[{"key":"A","text":"经验效标法：通过比较已知效标群体与对照群体的作答差异筛选条目，而非只靠题目表面内容。"},{"key":"B","text":"效度量表：用于判断作答一致性、夸大、淡化、防御或其他反应风格，决定剖面能否解释。"},{"key":"C","text":"临床量表：单一量表超过界值就自动得到诊断。"},{"key":"D","text":"剖面解释：逐个量表照说明书解释，忽略整体关系。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A、B分别准确描述了“经验效标法”和“效度量表”。C、D是常见误区，不能作为规范理解或操作依据。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('a3b282ab-f508-5b3c-bb03-56be4c04059b'::uuid, '61bfb40e-f681-5397-b982-68e86ff747d4'::uuid, 'multi', '关于本章核心概念，下列哪些表述正确？（多选）', '[{"key":"A","text":"临床量表：反映若干症状、人格和适应相关经验模式的标准化量表，需结合剖面解释。"},{"key":"B","text":"剖面解释：综合效度、整体形态、最高点、量表组合、基率和转介问题解释分数模式。"},{"key":"C","text":"人格病理：有某种特质或人际困难就等于人格障碍。"},{"key":"D","text":"维度评估：维度分数高低可以直接替代完整诊断。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A、B分别准确描述了“临床量表”和“剖面解释”。C、D是常见误区，不能作为规范理解或操作依据。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('4dcae8c2-78e7-5b8b-8c98-e1936c215c1e'::uuid, '61bfb40e-f681-5397-b982-68e86ff747d4'::uuid, 'multi', '关于本章核心概念，下列哪些表述正确？（多选）', '[{"key":"A","text":"人格病理：长期、广泛、僵化并导致显著痛苦或功能损害的人格体验和行为模式。"},{"key":"B","text":"维度评估：在连续维度上描述人格特质和功能严重度，保留个体差异和变化空间。"},{"key":"C","text":"诊断边界：测验报告可以自动生成最终诊断。"},{"key":"D","text":"人格病理反馈：直接宣告“你就是某型人格”，忽略不确定性。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A、B分别准确描述了“人格病理”和“维度评估”。C、D是常见误区，不能作为规范理解或操作依据。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('a0adeeaa-51b8-54e2-8536-2d044e4650a7'::uuid, '61bfb40e-f681-5397-b982-68e86ff747d4'::uuid, 'blank', '请填写概念：____是指通过比较已知效标群体与对照群体的作答差异筛选条目，而非只靠题目表面内容。', NULL, '{"correct":["经验效标法"]}'::jsonb, '答案是“经验效标法”。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('a2afd210-4b29-5f25-b72b-5b0da06b9d24'::uuid, '61bfb40e-f681-5397-b982-68e86ff747d4'::uuid, 'short', '简答题：说明“经验效标法”与“效度量表”各自的含义，并指出在MMPI与人格病理评估中的应用要点。', NULL, '{"reference":"参考要点：\n1）经验效标法：通过比较已知效标群体与对照群体的作答差异筛选条目，而非只靠题目表面内容。\n2）效度量表：用于判断作答一致性、夸大、淡化、防御或其他反应风格，决定剖面能否解释。\n3）应用：理解MMPI量表名称不等于条目内容或单一诊断。\n4）应用：解释临床量表前先检查漏答、随机和过度报告指标。\n5）作答时应避免把两者混为一谈，并结合阶段目标说明使用时机。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('4d33c502-8a69-5458-9fba-d86002a83897'::uuid, '61bfb40e-f681-5397-b982-68e86ff747d4'::uuid, 'case', '案例题：MMPI剖面中多个临床量表显著升高，但效度指标提示随机作答和夸大。转介方要求立即给出人格障碍诊断。请说明处理。', NULL, '{"reference":"参考要点：效度优先，当前剖面可能不可解释，不能按临床量表下诊断；检查施测条件、理解、动机和漏答，必要时重新评估；人格障碍需长期、跨情境、功能损害和鉴别信息；向转介方说明限制与需要补充的访谈、多源资料；反馈时避免污名化。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('d7efeaa1-dfa6-5de7-b1eb-25e2b1a0ae6e'::uuid, '61bfb40e-f681-5397-b982-68e86ff747d4'::uuid, 'single', '围绕“经验效标法”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"量表名称直接说明受测者患有同名障碍。"},{"key":"B","text":"理解MMPI量表名称不等于条目内容或单一诊断。"},{"key":"C","text":"依据概念进行判断：通过比较已知效标群体与对照群体的作答差异筛选条目，而非只靠题目表面内容。"},{"key":"D","text":"向来访者说明：这些量表来自群体作答模式，名称不能被直接当作个人诊断。"}]'::jsonb, '{"correct":"A"}'::jsonb, '应避免：量表名称直接说明受测者患有同名障碍。。规范依据是：通过比较已知效标群体与对照群体的作答差异筛选条目，而非只靠题目表面内容。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('3c1524c0-62ca-5524-b56b-0b9f4345d431'::uuid, '61bfb40e-f681-5397-b982-68e86ff747d4'::uuid, 'single', '围绕“效度量表”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"解释临床量表前先检查漏答、随机和过度报告指标。"},{"key":"B","text":"临床量表高分时可以跳过效度检查。"},{"key":"C","text":"依据概念进行判断：用于判断作答一致性、夸大、淡化、防御或其他反应风格，决定剖面能否解释。"},{"key":"D","text":"向来访者说明：先确认答题方式是否有效，后面的分数解释才有意义。"}]'::jsonb, '{"correct":"B"}'::jsonb, '应避免：临床量表高分时可以跳过效度检查。。规范依据是：用于判断作答一致性、夸大、淡化、防御或其他反应风格，决定剖面能否解释。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('2e3f62c5-545e-5b79-bba0-a3b8d83be702'::uuid, '61bfb40e-f681-5397-b982-68e86ff747d4'::uuid, 'single', '围绕“临床量表”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"关注多个量表的相对高低和临床资料。"},{"key":"B","text":"依据概念进行判断：反映若干症状、人格和适应相关经验模式的标准化量表，需结合剖面解释。"},{"key":"C","text":"单一量表超过界值就自动得到诊断。"},{"key":"D","text":"向来访者说明：临床量表提供模式线索，不能由一个高分直接确定诊断。"}]'::jsonb, '{"correct":"C"}'::jsonb, '应避免：单一量表超过界值就自动得到诊断。。规范依据是：反映若干症状、人格和适应相关经验模式的标准化量表，需结合剖面解释。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('79373231-2c49-5332-8543-a7433fa4a2f6'::uuid, '61bfb40e-f681-5397-b982-68e86ff747d4'::uuid, 'single', '围绕“剖面解释”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"先看剖面是否有效，再识别共同主题和不一致。"},{"key":"B","text":"依据概念进行判断：综合效度、整体形态、最高点、量表组合、基率和转介问题解释分数模式。"},{"key":"C","text":"向来访者说明：我们更关注整组分数形成的模式，而不是孤立看一项。"},{"key":"D","text":"逐个量表照说明书解释，忽略整体关系。"}]'::jsonb, '{"correct":"D"}'::jsonb, '应避免：逐个量表照说明书解释，忽略整体关系。。规范依据是：综合效度、整体形态、最高点、量表组合、基率和转介问题解释分数模式。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('26e1089e-e5a6-5e40-9913-5ed8b0a3c36c'::uuid, '61bfb40e-f681-5397-b982-68e86ff747d4'::uuid, 'single', '围绕“人格病理”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"有某种特质或人际困难就等于人格障碍。"},{"key":"B","text":"评估跨情境稳定性、发展历史和功能损害。"},{"key":"C","text":"依据概念进行判断：长期、广泛、僵化并导致显著痛苦或功能损害的人格体验和行为模式。"},{"key":"D","text":"向来访者说明：人格病理需要看长期、跨情境和功能影响，不是一次困难或单个特质。"}]'::jsonb, '{"correct":"A"}'::jsonb, '应避免：有某种特质或人际困难就等于人格障碍。。规范依据是：长期、广泛、僵化并导致显著痛苦或功能损害的人格体验和行为模式。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('7461d67e-423a-5276-9445-17919cd5ab8f'::uuid, '61bfb40e-f681-5397-b982-68e86ff747d4'::uuid, 'single', '围绕“维度评估”开展评估时，下列哪一种做法最需要避免？', '[{"key":"A","text":"同时描述负性情感、疏离等特质及自我人际功能。"},{"key":"B","text":"维度分数高低可以直接替代完整诊断。"},{"key":"C","text":"依据概念进行判断：在连续维度上描述人格特质和功能严重度，保留个体差异和变化空间。"},{"key":"D","text":"向来访者说明：维度帮助描述程度和组合，但仍需结合功能和临床判断。"}]'::jsonb, '{"correct":"B"}'::jsonb, '应避免：维度分数高低可以直接替代完整诊断。。规范依据是：在连续维度上描述人格特质和功能严重度，保留个体差异和变化空间。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('16f0f19b-116c-5065-a60e-0c91e080dde1'::uuid, '3505ce48-30a4-59a4-8aaf-97b308ec5c5a'::uuid, 'single', '下列哪一概念最符合这一描述：“通过病史、访谈、观察和标准化测验理解大脑功能与认知、情绪和行为表现关系的综合评估。”？', '[{"key":"A","text":"神经心理评估"},{"key":"B","text":"个体内差异"},{"key":"C","text":"表现效度"},{"key":"D","text":"病前功能估计"}]'::jsonb, '{"correct":"A"}'::jsonb, '正确概念是“神经心理评估”。用于识别认知强弱、鉴别困难来源和制定干预。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('a9c4202d-dd1d-5e95-a9f7-835074a71eaa'::uuid, '3505ce48-30a4-59a4-8aaf-97b308ec5c5a'::uuid, 'single', '下列哪一概念最符合这一描述：“评估常涉及注意、记忆、语言、视空间、执行功能、加工速度和运动等相互关联的功能。”？', '[{"key":"A","text":"表现效度"},{"key":"B","text":"认知领域"},{"key":"C","text":"病前功能估计"},{"key":"D","text":"固定与灵活测验组合"}]'::jsonb, '{"correct":"B"}'::jsonb, '正确概念是“认知领域”。根据转介问题选择多个领域并比较模式。')
