insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('2653252b-1692-5e3b-9943-2ca1f5f97ba4'::uuid, '3505ce48-30a4-59a4-8aaf-97b308ec5c5a'::uuid, 'single', '下列哪一概念最符合这一描述：“比较同一个体不同能力领域的相对强项与弱项，而不只看与常模的总体差距。”？', '[{"key":"A","text":"病前功能估计"},{"key":"B","text":"固定与灵活测验组合"},{"key":"C","text":"个体内差异"},{"key":"D","text":"脑行为推断"}]'::jsonb, '{"correct":"C"}'::jsonb, '正确概念是“个体内差异”。平均总分下仍识别显著记忆弱项和视觉优势。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('1795a4ec-1121-5b27-9e34-13c5f5e52fde'::uuid, '3505ce48-30a4-59a4-8aaf-97b308ec5c5a'::uuid, 'single', '下列哪一概念最符合这一描述：“判断受评者是否提供了可解释的充分投入和一致表现，不等同于简单指控装病。”？', '[{"key":"A","text":"固定与灵活测验组合"},{"key":"B","text":"脑行为推断"},{"key":"C","text":"功能建议"},{"key":"D","text":"表现效度"}]'::jsonb, '{"correct":"D"}'::jsonb, '正确概念是“表现效度”。结合专门指标、行为观察和情境解释低投入。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('7bbf196b-e79d-5249-8293-4dd650f93967'::uuid, '3505ce48-30a4-59a4-8aaf-97b308ec5c5a'::uuid, 'single', '下列哪一概念最符合这一描述：“根据教育、职业、阅读等资料估计问题出现前的能力水平，为判断变化提供基线。”？', '[{"key":"A","text":"病前功能估计"},{"key":"B","text":"脑行为推断"},{"key":"C","text":"功能建议"},{"key":"D","text":"神经心理评估"}]'::jsonb, '{"correct":"A"}'::jsonb, '正确概念是“病前功能估计”。高教育者当前平均分可能仍代表明显下降。')
