insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('64ef1120-2ec4-599d-9064-84da2f6d1286'::uuid, '3505ce48-30a4-59a4-8aaf-97b308ec5c5a'::uuid, 'single', '下列哪一概念最符合这一描述：“固定组合便于全面和比较，灵活组合根据转介问题和发现调整，两者各有优缺点。”？', '[{"key":"A","text":"功能建议"},{"key":"B","text":"固定与灵活测验组合"},{"key":"C","text":"神经心理评估"},{"key":"D","text":"认知领域"}]'::jsonb, '{"correct":"B"}'::jsonb, '正确概念是“固定与灵活测验组合”。先覆盖核心领域，再根据异常追加测验。')
