insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('1813e446-ce75-5b8a-b9c9-7a233ef893ea'::uuid, '3505ce48-30a4-59a4-8aaf-97b308ec5c5a'::uuid, 'single', '下列哪一概念最符合这一描述：“依据认知模式、病史、医学资料和功能表现形成关于机制的概率性解释。”？', '[{"key":"A","text":"神经心理评估"},{"key":"B","text":"认知领域"},{"key":"C","text":"脑行为推断"},{"key":"D","text":"个体内差异"}]'::jsonb, '{"correct":"C"}'::jsonb, '正确概念是“脑行为推断”。把记忆、执行和情绪资料与病程共同分析。')
