insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('c94ca165-79d7-5738-adb5-0578a408cf1b'::uuid, '3505ce48-30a4-59a4-8aaf-97b308ec5c5a'::uuid, 'single', '应用情境：先覆盖核心领域，再根据异常追加测验。此时最需要优先依据哪一概念？', '[{"key":"A","text":"神经心理评估"},{"key":"B","text":"固定与灵活测验组合"},{"key":"C","text":"认知领域"},{"key":"D","text":"个体内差异"}]'::jsonb, '{"correct":"B"}'::jsonb, '该情境考查“固定与灵活测验组合”：固定组合便于全面和比较，灵活组合根据转介问题和发现调整，两者各有优缺点。')
