insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('ed926278-1f3a-5db5-a4d2-445961b142a3'::uuid, '3505ce48-30a4-59a4-8aaf-97b308ec5c5a'::uuid, 'multi', '关于本章核心概念，下列哪些表述正确？（多选）', '[{"key":"A","text":"神经心理评估：通过病史、访谈、观察和标准化测验理解大脑功能与认知、情绪和行为表现关系的综合评估。"},{"key":"B","text":"认知领域：评估常涉及注意、记忆、语言、视空间、执行功能、加工速度和运动等相互关联的功能。"},{"key":"C","text":"个体内差异：总分正常就说明所有功能正常。"},{"key":"D","text":"表现效度：一次表现效度失败就证明故意欺骗。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A、B分别准确描述了“神经心理评估”和“认知领域”。C、D是常见误区，不能作为规范理解或操作依据。')
