insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('af6783be-b1ce-5652-b47a-73d8c4c29a4c'::uuid, '3505ce48-30a4-59a4-8aaf-97b308ec5c5a'::uuid, 'short', '简答题：说明“神经心理评估”与“认知领域”各自的含义，并指出在神经心理评估中的应用要点。', NULL, '{"reference":"参考要点：\n1）神经心理评估：通过病史、访谈、观察和标准化测验理解大脑功能与认知、情绪和行为表现关系的综合评估。\n2）认知领域：评估常涉及注意、记忆、语言、视空间、执行功能、加工速度和运动等相互关联的功能。\n3）应用：用于识别认知强弱、鉴别困难来源和制定干预。\n4）应用：根据转介问题选择多个领域并比较模式。\n5）作答时应避免把两者混为一谈，并结合阶段目标说明使用时机。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('db57a334-176d-57d4-88b1-e7012ac3540c'::uuid, '3505ce48-30a4-59a4-8aaf-97b308ec5c5a'::uuid, 'case', '案例题：高学历成年人主诉记忆下降，总分仍在平均范围，但与估计病前水平相比明显降低且执行功能也下降。请说明解释原则。', NULL, '{"reference":"参考要点：不能仅凭常模平均排除下降；结合病前功能估计和个体内差异；检查表现效度、情绪、睡眠、药物和医学因素；观察记忆与执行模式；避免单一分数定位病因；与病史和功能变化整合，提出医学检查、补偿策略和随访建议。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('c02beddf-2ec0-5c68-a994-9e5a910795dc'::uuid, '84ec1ebb-8d45-5538-8a91-da02dae58d25'::uuid, 'single', '下列哪一概念最符合这一描述：“把能力和行为放在年龄、发展阶段、学习机会和变化轨迹中理解。”？', '[{"key":"A","text":"发展性评估"},{"key":"B","text":"发展史"},{"key":"C","text":"适龄常模"},{"key":"D","text":"发育行为观察"}]'::jsonb, '{"correct":"A"}'::jsonb, '正确概念是“发展性评估”。同一行为在幼儿和青少年阶段的意义不同。')
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('ed9d1fc8-c537-5ba9-aa59-35975af742b3'::uuid, '84ec1ebb-8d45-5538-8a91-da02dae58d25'::uuid, 'single', '下列哪一概念最符合这一描述：“综合儿童本人、家长、教师和其他照顾者在不同情境中的观察。”？', '[{"key":"A","text":"适龄常模"},{"key":"B","text":"多信息提供者"},{"key":"C","text":"发育行为观察"},{"key":"D","text":"自闭症与多动评估"}]'::jsonb, '{"correct":"B"}'::jsonb, '正确概念是“多信息提供者”。比较家庭与学校报告并探索情境差异。')
