insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('950bfc4b-f47d-5796-ad4b-323b5596c404'::uuid, '84ec1ebb-8d45-5538-8a91-da02dae58d25'::uuid, 'single', '下列哪一概念最符合这一描述：“收集孕产、里程碑、语言、运动、学习、医疗和社会情绪发展过程。”？', '[{"key":"A","text":"发育行为观察"},{"key":"B","text":"自闭症与多动评估"},{"key":"C","text":"发展史"},{"key":"D","text":"学习与智力评估"}]'::jsonb, '{"correct":"C"}'::jsonb, '正确概念是“发展史”。关注何时出现偏离、是否退步及环境变化。')
