insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('b00115ce-7130-56d3-a06f-1cb9243641a8'::uuid, '84ec1ebb-8d45-5538-8a91-da02dae58d25'::uuid, 'single', '下列哪一概念最符合这一描述：“使用与年龄、语言、文化和教育背景相匹配的参照资料解释表现。”？', '[{"key":"A","text":"自闭症与多动评估"},{"key":"B","text":"学习与智力评估"},{"key":"C","text":"合理调整"},{"key":"D","text":"适龄常模"}]'::jsonb, '{"correct":"D"}'::jsonb, '正确概念是“适龄常模”。学龄前儿童使用对应年龄段规范版本。')
