insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('6bf799a4-a373-5365-89c7-2415adc0c312'::uuid, '84ec1ebb-8d45-5538-8a91-da02dae58d25'::uuid, 'short', '简答题：说明“发展性评估”与“多信息提供者”各自的含义，并指出在发育行为与特殊人群评估中的应用要点。', NULL, '{"reference":"参考要点：\n1）发展性评估：把能力和行为放在年龄、发展阶段、学习机会和变化轨迹中理解。\n2）多信息提供者：综合儿童本人、家长、教师和其他照顾者在不同情境中的观察。\n3）应用：同一行为在幼儿和青少年阶段的意义不同。\n4）应用：比较家庭与学校报告并探索情境差异。\n5）作答时应避免把两者混为一谈，并结合阶段目标说明使用时机。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('54d9d94b-75e4-5d41-b224-8818057d54f6'::uuid, '84ec1ebb-8d45-5538-8a91-da02dae58d25'::uuid, 'case', '案例题：教师报告儿童在课堂极度分心，家长称在家专注良好，筛查问卷结果也不一致。请设计进一步评估。', NULL, '{"reference":"参考要点：不把不一致简单归因为谁不可信；收集发展、学习、睡眠、情绪和家庭学校情境；获取多信息提供者资料；进行课堂或结构化观察；选择适龄、适文化工具；评估注意冲动的跨情境和功能损害；鉴别教学、焦虑、学习困难等因素；反馈时说明情境差异和支持建议。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('21f7c482-b0f0-588c-b4aa-ca91fe2cadbf'::uuid, '60f27810-dcbd-5a78-bcf2-f94f3d41936f'::uuid, 'single', '下列哪一概念最符合这一描述：“把评估本身作为合作性干预，通过共同问题、体验和反馈促进理解与改变。”？', '[{"key":"A","text":"治疗性评估"},{"key":"B","text":"结果监测"},{"key":"C","text":"被动数字数据"},{"key":"D","text":"多模态评估"}]'::jsonb, '{"correct":"A"}'::jsonb, '正确概念是“治疗性评估”。让来访提出希望评估回答的问题，并共同讨论结果意义。')
