insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('9b0b2966-7abf-5d80-8eba-8fc2f07c4b80'::uuid, '60f27810-dcbd-5a78-bcf2-f94f3d41936f'::uuid, 'multi', '关于本章核心概念，下列哪些表述正确？（多选）', '[{"key":"A","text":"治疗性评估：把评估本身作为合作性干预，通过共同问题、体验和反馈促进理解与改变。"},{"key":"B","text":"合作反馈：评估者与受评者共同检验结果、差异和意义，允许修正并连接现实目标。"},{"key":"C","text":"结果监测：每次分数波动都代表真实恶化或改善。"},{"key":"D","text":"被动数字数据：数据自动产生就无需同意，且能直接读出心理状态。"}]'::jsonb, '{"correct":["A","B"]}'::jsonb, 'A、B分别准确描述了“治疗性评估”和“合作反馈”。C、D是常见误区，不能作为规范理解或操作依据。')
