insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('439801a9-d3be-5f85-af9d-67c3a3174fc7'::uuid, '60f27810-dcbd-5a78-bcf2-f94f3d41936f'::uuid, 'short', '简答题：说明“治疗性评估”与“合作反馈”各自的含义，并指出在治疗性、数智化评估与课程整合中的应用要点。', NULL, '{"reference":"参考要点：\n1）治疗性评估：把评估本身作为合作性干预，通过共同问题、体验和反馈促进理解与改变。\n2）合作反馈：评估者与受评者共同检验结果、差异和意义，允许修正并连接现实目标。\n3）应用：让来访提出希望评估回答的问题，并共同讨论结果意义。\n4）应用：询问结果哪些符合、哪些不符合以及有什么新问题。\n5）作答时应避免把两者混为一谈，并结合阶段目标说明使用时机。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, chapter_id, type, stem, options, answer, explanation) values ('0fe7f365-12b9-594a-9604-6c28325f202b'::uuid, '60f27810-dcbd-5a78-bcf2-f94f3d41936f'::uuid, 'case', '案例题：机构计划用手机数据和AI语音分析自动筛查抑郁与自杀风险，并把高风险名单直接发给管理者。请评估该方案。', NULL, '{"reference":"参考要点：明确评估目的和模型效度；取得具体知情同意并实施数据最小化；检查算法偏差、误报漏报和群体适用性；高风险必须由专业人员及时复核，不能由算法直接诊断；限定管理者访问和用途；建立紧急处置、退出、申诉、数据保存与安全机制；持续监测效果。"}'::jsonb, NULL)
on conflict (id) do update set chapter_id = excluded.chapter_id, type = excluded.type, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;

